#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Deploys Cerium's relay to https://cerium.nonlooped.xyz and walks
# through signing in from this computer and a phone. Run from anywhere, in Git Bash on Windows:
#   bash apps/relay/scripts/deploy-relay.sh
# Safe to re-run: settings the relay already has are kept, and finished steps can be skipped.

run_wizard() {

TOTAL_STAGES=9
RELAY_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ROOT_DIR="$(cd "$RELAY_DIR/../.." && pwd)"
SITE="https://cerium.nonlooped.xyz"
# Clerk's production instance for the site answers at clerk.<site>, and its publishable key is
# pk_live_ followed by that host and a $, base64-encoded without padding.
CLERK_HOST="clerk.${SITE#https://}"
CLERK_PUBLISHABLE_KEY="pk_live_$(printf '%s$' "$CLERK_HOST" | base64 | tr -d '\n=')"
REPO="https://github.com/CeriumHQ/cerium"
SECRETS_FILE=""
# The secrets' temporary file goes when the wizard ends, then its folder, only if that's empty.
trap 'if [[ -n "$SECRETS_FILE" ]]; then rm -f "$SECRETS_FILE"; rmdir "${SECRETS_FILE%/*}" 2>/dev/null || true; fi' EXIT

wrangler() { (cd "$RELAY_DIR" && npx --yes wrangler "$@"); }

banner "Put Cerium's relay online and connect your devices"

stage "Push your work to GitHub"
ahead=$(git -C "$ROOT_DIR" rev-list --count '@{upstream}..HEAD' 2>/dev/null || echo "?")
if [[ "$ahead" == "0" ]]; then
  say "Everything on main is already on GitHub."
else
  say "Main has $ahead commit(s) GitHub doesn't have yet, including accounts and notifications."
  say "Pushing them makes GitHub build a new Cerium Nightly installer, which you install later on."
  if confirm "Push main to GitHub now?"; then
    if git -C "$ROOT_DIR" push origin main; then
      note "GitHub is building the installer now; it takes a while. You'll install it in stage 6."
    else
      SKIPPED+=("push main to GitHub (git push origin main), then install the new nightly")
      warn "The push didn't go through. Fix what git says above, then push and re-run."
    fi
  else
    SKIPPED+=("push main to GitHub (git push origin main), then install the new nightly")
    warn "Skipped. Your installed Cerium can't sign in until a nightly with accounts is installed."
  fi
fi
pause "Press Enter to continue."

stage "Log in to Cloudflare"
say "Cloudflare runs the relay. Its command-line tool, Wrangler, needs to log in once."
if wrangler whoami 2>/dev/null | grep -q "You are logged in"; then
  say "Wrangler is already logged in."
else
  step "A browser page opens: log in with the Cloudflare account that has nonlooped.xyz."
  step "Then select Allow to let Wrangler manage that account."
  pause "Press Enter to open the login page."
  wrangler login || { warn "Wrangler didn't log in. Re-run this wizard to try again."; exit 1; }
fi
wrangler whoami | grep -E "logged in|Account Name|│" || true
open_url "https://dash.cloudflare.com/"
step "In the dashboard, check that nonlooped.xyz is listed under this account's domains."
note "If it's under another account, log in to that one instead: npx wrangler logout, then re-run."
pause "Press Enter once nonlooped.xyz is in this account."

stage "The relay's settings"
say "The relay needs four settings, stored by Cloudflare as encrypted secrets:"
note "  CLERK_PUBLISHABLE_KEY, CLERK_JWT_KEY  Clerk's production instance at $CLERK_HOST"
note "  VAPID_PUBLIC_KEY, VAPID_PRIVATE_KEY    a new key pair that signs push notifications"
note "apps/relay/.dev.vars holds the development instance's keys and stays local."
existing=$(wrangler secret list 2>/dev/null || true)
missing=()
for name in CLERK_PUBLISHABLE_KEY CLERK_JWT_KEY VAPID_PUBLIC_KEY VAPID_PRIVATE_KEY; do
  [[ "$existing" == *"\"$name\""* ]] || missing+=("$name")
done
# A relay still serving another instance's key (a development pk_test_ one) gets both Clerk keys anew.
live_config=$(curl -fsS --max-time 15 "$SITE/api/config" 2>/dev/null || true)
if [[ "$live_config" == *'"publishableKey"'* && "$live_config" != *"\"$CLERK_PUBLISHABLE_KEY\""* ]]; then
  warn "The relay signs in with another Clerk instance; its keys are replaced with production's."
  for name in CLERK_PUBLISHABLE_KEY CLERK_JWT_KEY; do
    [[ " ${missing[*]} " == *" $name "* ]] || missing+=("$name")
  done
fi
if (( ${#missing[@]} == 0 )); then
  say "The relay has all four already; they're kept as they are."
else
  # Node fetches the production instance's JWT public key from its Frontend API and writes only
  # what's missing to a private temporary file, deleted when this wizard ends. Values go in through
  # the environment rather than arguments, which Git Bash mangles.
  SECRETS_FILE=$(CERIUM_MISSING="${missing[*]}" CERIUM_CLERK_HOST="$CLERK_HOST" \
    CERIUM_CLERK_KEY="$CLERK_PUBLISHABLE_KEY" node --input-type=module <<'NODE'
import { createPublicKey } from "node:crypto";
import { writeFileSync, mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const { CERIUM_MISSING, CERIUM_CLERK_HOST, CERIUM_CLERK_KEY } = process.env;
const wanted = new Set(CERIUM_MISSING.split(" "));
const all = { CLERK_PUBLISHABLE_KEY: CERIUM_CLERK_KEY };
// The key and the instance it names go up together: either alone verifies nothing.
if (wanted.has("CLERK_PUBLISHABLE_KEY") || wanted.has("CLERK_JWT_KEY")) {
  wanted.add("CLERK_PUBLISHABLE_KEY").add("CLERK_JWT_KEY");
  const response = await fetch(`https://${CERIUM_CLERK_HOST}/.well-known/jwks.json`).catch((error) => {
    console.error(`Couldn't reach ${CERIUM_CLERK_HOST}: ${error.message}`);
    process.exit(1);
  });
  const { keys } = await response.json();
  all.CLERK_JWT_KEY = createPublicKey({ key: keys[0], format: "jwk" })
    .export({ type: "spki", format: "pem" })
    .trim();
}
if (wanted.has("VAPID_PUBLIC_KEY") || wanted.has("VAPID_PRIVATE_KEY")) {
  // A new pair goes up whole: half of one matches nothing.
  wanted.add("VAPID_PUBLIC_KEY").add("VAPID_PRIVATE_KEY");
  const pair = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign"]);
  all.VAPID_PUBLIC_KEY = Buffer.from(await crypto.subtle.exportKey("raw", pair.publicKey)).toString("base64url");
  all.VAPID_PRIVATE_KEY = (await crypto.subtle.exportKey("jwk", pair.privateKey)).d;
}
const secrets = Object.fromEntries([...wanted].map((name) => [name, all[name]]));
const file = join(mkdtempSync(join(tmpdir(), "cerium-relay-")), "secrets.json");
writeFileSync(file, JSON.stringify(secrets), { mode: 0o600 });
process.stdout.write(file.replaceAll("\\", "/"));
NODE
  ) || {
    warn "Couldn't prepare the settings. Check that Clerk's production instance has ${SITE#https://}"
    warn "as its domain with every DNS record verified (dashboard.clerk.com → Domains), then re-run."
    exit 1
  }
  say "Ready to upload: ${missing[*]}"
  note "They go up with the relay in the next stage."
fi
pause "Press Enter to continue."

stage "Publish the relay"
say "This builds the web app and the relay, then publishes both at $SITE."
note "Cloudflare also creates the cerium.nonlooped.xyz address and its certificate."
note "Everything stays on Cloudflare's free plan."
if confirm "Publish the relay now?"; then
  # Earlier releases' web apps stay up for the computers still running them.
  (cd "$ROOT_DIR" && bun run --cwd apps/relay builds && bun run --cwd apps/relay build)
  if [[ -n "$SECRETS_FILE" ]]; then
    wrangler deploy --secrets-file "$SECRETS_FILE"
  else
    wrangler deploy
  fi
else
  SKIPPED+=("publish the relay: bash apps/relay/scripts/deploy-relay.sh")
  warn "Skipped. Nothing was published."
fi
pause "Press Enter to continue."

stage "Check the relay answers"
say "Asking $SITE/api/config, which names the Clerk instance and the push key."
note "A new address and certificate can take a few minutes to start answering."
while true; do
  config=$(curl -fsS --max-time 15 "$SITE/api/config" 2>/dev/null || true)
  if [[ "$config" == *publishableKey* && "$config" == *vapidPublicKey* ]]; then
    say "${GREEN}✓${RESET} The relay answers, with sign-in and notifications set up."
    break
  fi
  if [[ "$config" == *publishableKey* ]]; then
    warn "The relay answers, but without a push key: re-run this wizard to upload it."
    break
  fi
  confirm "No answer yet. Wait 30 seconds and try again?" || {
    SKIPPED+=("check $SITE/api/config answers")
    break
  }
  sleep 30
done
pause "Press Enter to continue."

stage "Install the new Cerium Nightly"
say "Your installed Cerium Nightly is older than accounts. GitHub builds the new one from what you pushed."
open_url "$REPO/actions"
step "Wait for the newest CI run on main to finish (a green tick)."
open_url "$REPO/releases"
step "Open the newest Pre-release (a nightly) and download the .exe under Assets."
step "Quit Cerium Nightly if it's running."
step "Run the downloaded installer; it replaces the old version."
pause "Press Enter once the new Cerium Nightly is installed and open."

stage "Sign in on this computer"
step "In Cerium, open Settings (the gear at the bottom left) → Account."
step "Select Sign in. Your browser opens Cerium's sign-in page at $SITE."
step "Sign in with Google, GitHub, X or an email and password."
step "The page asks to connect this computer: select Connect, then go back to Cerium."
note "The first device of an account is let in at once; later ones wait for you to allow them."
pause "Press Enter once Settings → Account shows you signed in."

stage "Connect your phone"
step "On your phone, open $SITE in its browser."
step "Add it to the Home Screen: on iPhone or iPad, tap Share → Add to Home Screen;"
step "on Android, tap the ⋮ menu → Install app (or Add to Home screen)."
step "Open Cerium from the Home Screen and tap Sign in, then sign in as on the computer."
step "Back in Cerium on the phone, it waits for one of your computers to let it in."
step "On this computer, Cerium says your phone wants to join: select Review, then Allow."
pause "Press Enter once your phone shows your computer's threads."

stage "Turn on notifications"
step "On the phone, open Settings → Notifications in Cerium."
step "Turn on Allow notifications, and allow them when the phone asks."
step "Choose which ones you want: an agent needs you, a thread finishes, something fails."
say "To try it: start a thread on this computer, then lock the phone or switch apps."
note "You aren't notified about a thread you have open on a screen, or while Cerium is open on the phone."
pause "Press Enter to finish."

finish
}

run_wizard "$@"; exit
